import sys

def main():
    input_data = sys.stdin.read().split()
    idx = 0

    n = int(input_data[idx]); idx += 1

    parent_list = [0] * (n + 1)
    key_list = [0] * (n + 1)
    left_child = [0] * (n + 1)
    right_child = [0] * (n + 1)

    root = 0

    for i in range(1, n + 1):
        p = int(input_data[idx]); idx += 1
        k_val = int(input_data[idx]); idx += 1

        parent_list[i] = p
        key_list[i] = k_val

        if p == -1:
            root = i
        else:
            if k_val < key_list[p]:
                left_child[p] = i
            else:
                right_child[p] = i

    k_queries = int(input_data[idx]); idx += 1

    queries = []
    for _ in range(k_queries):
        queries.append(int(input_data[idx])); idx += 1

    is_leaf = [False] * (n + 1)
    for i in range(1, n + 1):
        if left_child[i] == 0 and right_child[i] == 0:
            is_leaf[i] = True

    leaf_keys = {}
    for i in range(1, n + 1):

        if is_leaf[i]:
            leaf_keys[i] = key_list[i]

    def get_path(node, target):
        path = []
        curr = node
        while curr != 0:
            path.append(curr)
            if key_list[curr] > target:
                curr = left_child[curr]
            else:
                curr = right_child[curr]
        return path

    results = []

    for q_key in queries:
        path = get_path(root, q_key)
        total_sum = 0.0
        count = 0

        for i, node in enumerate(path):
            if is_leaf[node]:
                break

            correct_next = left_child[node] if key_list[node] > q_key else right_child[node]
            wrong_next = right_child[node] if key_list[node] > q_key else left_child[node]

            if wrong_next == 0:
                continue

            sub_path = [wrong_next]
            curr = wrong_next
            while curr != 0 and not is_leaf[curr]:
                if key_list[curr] > q_key:
                    curr = left_child[curr]
                else:
                    curr = right_child[curr]
                sub_path.append(curr)

            if curr != 0 and is_leaf[curr]:
                total_sum += leaf_keys[curr]
                count += 1

        if count > 0:
            results.append(total_sum / count)
        else:
            results.append(0.0)

    for res in results:
        print(f"{res:.10f}")

if __name__ == "__main__":
    main()
